    12	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    13	    private static final BigDecimal ISS_RATE = new BigDecimal("0.05");
    14	
    15	    @Override
    16	    public void validate(Reservation reservation) {
    17	        if (reservation.getCompanyCnpj() == null || reservation.getCompanyCnpj().isBlank()) {
    18	            throw new IllegalArgumentException("CNPJ is required");
