    25	    @Override
    26	    public DocumentData generateDocument(Reservation reservation) {
    27	        DocumentData doc = new DocumentData();
    28	        doc.setTitle("Fatura de hospedagem");
    29	        doc.setReservationId(reservation.getId());
    30	        doc.setGuestName(reservation.getGuestName());
    31	        doc.setGuestCpf(null);
    32	        doc.setCompanyCnpj(reservation.getCompanyCnpj());
    33	        doc.setCompanyName(reservation.getCompanyName());
    34	        doc.setGuestPassport(null);
    35	        doc.setGuestCountry(null);
    36	        doc.setRoomNumber(reservation.getRoomNumber());
    37	        doc.setRoomType(reservation.getRoom().getType());
    38	        doc.setCheckIn(reservation.getCheckIn().format(DATE_FORMAT));
    39	        doc.setCheckOut(reservation.getCheckOut().format(DATE_FORMAT));
    40	        doc.setNights(reservation.getNights());
    41	        doc.setSubtotal(reservation.getSubtotal());
    42	        doc.setDiscount(reservation.getDiscount());
    43	        doc.setTotal(reservation.getTotal());
    44	        doc.setText(generateText(doc));
    45	        return doc;
    46	    }
    47	
    48	    private String generateText(DocumentData doc) {
    49	        StringBuilder sb = new StringBuilder();
    50	        sb.append("Fatura de hospedagem nº ").append(doc.getReservationId()).append("\n");
    51	        sb.append("Empresa: ").append(doc.getCompanyName())
    52	          .append(" (CNPJ ").append(formatCnpj(doc.getCompanyCnpj())).append(")\n");
    53	        sb.append("Hóspede: ").append(doc.getGuestName()).append("\n");
    54	        sb.append("Quarto: ").append(doc.getRoomNumber())
    55	          .append(" (").append(doc.getRoomType()).append(")\n");
    56	        sb.append("Entrada: ").append(doc.getCheckIn())
    57	          .append(" | Saída: ").append(doc.getCheckOut())
    58	          .append(" | ").append(doc.getNights()).append(doc.getNights() == 1 ? " diária" : " diárias").append("\n");
    59	        sb.append("Diárias: ").append(CURRENCY_FORMAT.format(doc.getSubtotal())).append("\n");
    60	
    61	        if (doc.getDiscount() != null && doc.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    62	            sb.append("Desconto: ").append(CURRENCY_FORMAT.format(doc.getDiscount())).append("\n");
    63	        }
    64	
    65	        sb.append("Total: ").append(CURRENCY_FORMAT.format(doc.getTotal())).append("\n");
    66	
    67	        BigDecimal iss = doc.getTotal().multiply(ISS_RATE).setScale(2, RoundingMode.HALF_EVEN);
    68	        sb.append("ISS retido (5%): ").append(CURRENCY_FORMAT.format(iss));
    69	
    70	        return sb.toString();
    71	    }
    72	
    73	    private String formatCnpj(String cnpj) {
    74	        if (cnpj.length() == 14) {
    75	            return cnpj.substring(0, 2) + "." + cnpj.substring(2, 5) + "." +
    76	                   cnpj.substring(5, 8) + "/" + cnpj.substring(8, 12) + "-" + cnpj.substring(12);
    77	        }
    78	        return cnpj;
    79	    }
    80	}
