     8	
     9	public class Reservation {
    10	    private Long id;
    11	    private final String roomNumber;
    12	    private final Room room;
    13	    private final String guestName;
    14	    private final String guestEmail;
    15	    private final String guestCpf;
    16	    private final String companyCnpj;
    17	    private final String companyName;
    18	    private final String guestPassport;
    19	    private final String guestCountry;
    20	    private final LocalDate checkIn;
    21	    private final LocalDate checkOut;
    22	    private final int guests;
    23	    private final RatePlan ratePlan;
    24	    private final DocumentGenerator documentGenerator;
    25	
    26	    private ReservationStatus status;
    27	    private BigDecimal amountPaid;
    28	    private BigDecimal refund;
    29	
    30	    public Reservation(String roomNumber, Room room, String guestName, String guestEmail,
    31	                      String guestCpf, String companyCnpj, String companyName,
    32	                      String guestPassport, String guestCountry,
    33	                      LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
    34	                      DocumentGenerator documentGenerator) {
    35	        this.roomNumber = roomNumber;
    36	        this.room = room;
    37	        this.guestName = guestName;
    38	        this.guestEmail = guestEmail;
    39	        this.guestCpf = guestCpf;
    40	        this.companyCnpj = companyCnpj;
    41	        this.companyName = companyName;
    42	        this.guestPassport = guestPassport;
    43	        this.guestCountry = guestCountry;
    44	        this.checkIn = checkIn;
    45	        this.checkOut = checkOut;
    46	        this.guests = guests;
    47	        this.ratePlan = ratePlan;
    48	        this.documentGenerator = documentGenerator;
    49	        this.status = ReservationStatus.PENDING;
    50	        this.amountPaid = BigDecimal.ZERO;
    51	        this.refund = null;
    52	    }
    53	
    54	    public void setId(Long id) {
    55	        this.id = id;
    56	    }
    57	
    58	    public boolean canConfirm() {
    59	        return status == ReservationStatus.PENDING;
    60	    }
    61	
    62	    public boolean canCheckIn() {
    63	        return status == ReservationStatus.CONFIRMED;
    64	    }
    65	
    66	    public boolean canCheckOut() {
    67	        return status == ReservationStatus.CHECKED_IN;
    68	    }
    69	
    70	    public boolean canCancel() {
    71	        return status == ReservationStatus.PENDING || status == ReservationStatus.CONFIRMED;
    72	    }
    73	
    74	    public void confirm() {
    75	        if (!canConfirm()) {
    76	            throw new IllegalStateException("Cannot confirm reservation in status " + status);
    77	        }
    78	        this.status = ReservationStatus.CONFIRMED;
    79	        this.amountPaid = getTotal();
    80	    }
    81	
    82	    public void checkIn() {
    83	        if (!canCheckIn()) {
    84	            throw new IllegalStateException("Cannot check in reservation in status " + status);
    85	        }
    86	        this.status = ReservationStatus.CHECKED_IN;
    87	    }
    88	
    89	    public void checkOut() {
    90	        if (!canCheckOut()) {
    91	            throw new IllegalStateException("Cannot check out reservation in status " + status);
    92	        }
    93	        this.status = ReservationStatus.CHECKED_OUT;
    94	    }
    95	
    96	    public void cancel() {
    97	        if (!canCancel()) {
    98	            throw new IllegalStateException("Cannot cancel reservation in status " + status);
    99	        }
   100	        this.status = ReservationStatus.CANCELLED;
   101	
   102	        if (ratePlan == RatePlan.STANDARD) {
   103	            this.refund = this.amountPaid;
   104	        } else {
   105	            this.refund = BigDecimal.ZERO;
   106	        }
   107	    }
   108	
   109	    public boolean isActive() {
   110	        return status != ReservationStatus.CANCELLED;
   111	    }
   112	
   113	    public boolean isPaid() {
   114	        return status == ReservationStatus.CONFIRMED ||
   115	               status == ReservationStatus.CHECKED_IN ||
   116	               status == ReservationStatus.CHECKED_OUT;
   117	    }
   118	
   119	    public boolean occupiesNight(LocalDate night) {
   120	        return !night.isBefore(checkIn) && night.isBefore(checkOut);
   121	    }
   122	
   123	    public int getNights() {
   124	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
   125	    }
   126	
   127	    public BigDecimal getSubtotal() {
   128	        BigDecimal subtotal = BigDecimal.ZERO;
   129	        LocalDate current = checkIn;
   130	
   131	        while (current.isBefore(checkOut)) {
   132	            BigDecimal nightRate = calculateNightRate(current);
   133	            subtotal = subtotal.add(nightRate);
   134	            current = current.plusDays(1);
   135	        }
   136	
   137	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
   138	    }
   139	
   140	    private BigDecimal calculateNightRate(LocalDate date) {
   141	        BigDecimal baseRate = room.getNightlyRate();
   142	
   143	        if (isHighSeason(date)) {
   144	            baseRate = baseRate.multiply(new BigDecimal("1.20"));
   145	        }
   146	
   147	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
   148	    }
   149	
   150	    private boolean isHighSeason(LocalDate date) {
   151	        Month month = date.getMonth();
   152	        int day = date.getDayOfMonth();
   153	
   154	        if (month == Month.JULY) {
   155	            return true;
   156	        }
   157	
   158	        if (month == Month.DECEMBER && day >= 15) {
   159	            return true;
   160	        }
   161	
   162	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
   163	            return true;
   164	        }
   165	
   166	        return false;
   167	    }
   168	
   169	    public BigDecimal getDiscount() {
