   127	    public BigDecimal getSubtotal() {
   128	        BigDecimal subtotal = BigDecimal.ZERO;
   129	        LocalDate current = checkIn;
   130	
   131	        while (current.isBefore(checkOut)) {
   132	            BigDecimal nightRate = calculateNightRate(current);
   133	            subtotal = subtotal.add(nightRate);
   134	            current = current.plusDays(1);
   135	        }
   136	
   137	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
